import { fireEvent, render, screen } from '@testing-library/react';
import { expect, it } from 'vitest';
import { TagInput } from './Solution';

const OPTIONS = ['Amsterdam', 'Berlin', 'Copenhagen', 'Zürich'];

function boot(props: Partial<Parameters<typeof TagInput>[0]> = {}) {
  const added: string[][] = [];
  const base = {
    options: OPTIONS,
    limit: 3,
    maxLength: 20,
    onChange: (tags: string[]) => added.push(tags.slice()),
  };
  const merged = { ...base, ...props } as Parameters<typeof TagInput>[0];
  const view = render(<TagInput {...merged} />);
  const input = () => screen.getByRole('combobox') as HTMLInputElement;
  const options = () => screen.queryAllByRole('option');
  const type = (value: string) => {
    fireEvent.change(input(), { target: { value } });
  };
  const key = (name: string) => {
    fireEvent.keyDown(input(), { key: name });
  };
  const attr = (name: string) => input().getAttribute(name);
  const text = (testid: string) => screen.getByTestId(testid).textContent;
  return { view, input, options, type, key, attr, text, added };
}

it('空输入时列表收起且 aria-expanded 为 false', () => {
  const t = boot();
  expect(t.attr('aria-expanded')).toBe('false');
  expect(t.attr('aria-controls')).toBe('tag-list');
  expect(t.attr('aria-autocomplete')).toBe('list');
  expect(t.text('chars')).toBe('0');
  expect(t.options().length).toBe(0);
});

it('无匹配候选时展示空态并清空 activedescendant', () => {
  const t = boot();
  t.type('Qm');
  expect(t.attr('aria-expanded')).toBe('true');
  expect(t.options().length).toBe(0);
  expect(t.text('no-match')).toBe('无匹配候选');
  expect(t.attr('aria-activedescendant') ?? '').toBe('');
});

it('重复按方向键循环高亮不越界', () => {
  const t = boot();
  fireEvent.focus(t.input());
  expect(t.attr('aria-expanded')).toBe('true');
  expect(t.options().length).toBe(4);
  for (let i = 0; i < 6; i += 1) t.key('ArrowDown');
  expect(t.attr('aria-activedescendant')).toBe('tag-opt-1');
  for (let i = 0; i < 3; i += 1) t.key('ArrowUp');
  expect(t.attr('aria-activedescendant')).toBe('tag-opt-2');
});

it('方向键循环高亮且 aria-selected 与 activedescendant 同步', () => {
  const t = boot();
  t.type('e');
  expect(t.options().length).toBe(3);
  t.key('ArrowDown');
  expect(t.attr('aria-activedescendant')).toBe('tag-opt-0');
  expect(t.options()[0].getAttribute('aria-selected')).toBe('true');
  t.key('End');
  expect(t.attr('aria-activedescendant')).toBe('tag-opt-2');
  t.key('ArrowDown');
  expect(t.attr('aria-activedescendant')).toBe('tag-opt-0');
  t.key('ArrowUp');
  expect(t.attr('aria-activedescendant')).toBe('tag-opt-2');
  t.key('Home');
  expect(t.attr('aria-activedescendant')).toBe('tag-opt-0');
  t.key('Escape');
  expect(t.attr('aria-activedescendant') ?? '').toBe('');
});

it('Enter 选中后 NFC 等价写法的重复标签不二次加入', () => {
  const t = boot({ options: ['Zürich', 'café', 'café'] });
  fireEvent.focus(t.input());
  t.key('ArrowDown');
  t.key('Enter');
  expect(t.text('tags')).toBe('Zürich');
  t.type('caf');
  t.key('ArrowDown');
  t.key('Enter');
  expect(t.text('tags')).toBe('Zürich|café');
  expect(t.text('announce')).toBe('已添加 café');
  t.key('ArrowDown');
  t.key('Enter');
  expect(t.text('tags')).toBe('Zürich|café');
  expect(t.text('announce')).toBe('已存在 café');
  t.type('');
  t.key('Backspace');
  expect(t.text('tags')).toBe('Zürich');
  expect(t.added.map((list) => list.length)).toEqual([1, 2, 1]);
});

it('超大 emoji 输入按字素族计数且不切断代理对', () => {
  const t = boot({ maxLength: 4 });
  t.type('🇨🇳🇺🇸🇻🇳abc');
  expect(t.input().value).toBe('🇨🇳🇺🇸🇻🇳a');
  expect(t.text('chars')).toBe('4');
  expect(t.text('remaining')).toBe('0');
  t.type('é́éa');
  expect(t.text('chars')).toBe('3');
  expect(t.input().value.length).toBe(5);
});

it('达到上限后拒绝新增并给出提示', () => {
  const t = boot({ limit: 2, options: ['Amsterdam', 'Berlin', 'Copenhagen'] });
  fireEvent.focus(t.input());
  t.key('ArrowDown');
  t.key('Enter');
  expect(t.text('tags')).toBe('Amsterdam');
  expect(t.text('limit-note')).toBe('');
  t.key('ArrowDown');
  t.key('ArrowDown');
  t.key('Enter');
  expect(t.text('tags')).toBe('Amsterdam|Berlin');
  t.type('Copen');
  expect(t.options().length).toBe(1);
  t.key('ArrowDown');
  t.key('Enter');
  expect(t.text('tags')).toBe('Amsterdam|Berlin');
  expect(t.text('limit-note')).toBe('最多 2 个标签');
});

