import { useState } from 'react';

export interface TagInputProps {
  options: string[];
  limit: number;
  maxLength?: number;
  onChange: (tags: string[]) => void;
}

/** 字素族切分：length 是 UTF-16 码元数，Array.from 是码点数，只有 Segmenter 才是"用户看到的字符"。 */
const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });

const graphemes = (value: string): string[] => [...segmenter.segment(value)].map((part) => part.segment);

const clampByGrapheme = (value: string, max: number): string => {
  const parts = graphemes(value);
  return parts.length > max ? parts.slice(0, max).join('') : value;
};

export function TagInput({ options, limit, maxLength = 20, onChange }: TagInputProps) {
  const [query, setQuery] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const [announce, setAnnounce] = useState('');

  const normalized = query.normalize('NFC');
  const matches = normalized.trim()
    ? options.filter((option) => option.normalize('NFC').toLowerCase().includes(normalized.toLowerCase()))
    : options.slice();
  const full = tags.length >= limit;
  const shown = open ? (normalized.trim().length > 0 ? matches : options.slice()) : [];

  const commit = (next: string[]) => {
    setTags(next);
    onChange(next);
  };

  const add = (candidate: string) => {
    const value = candidate.normalize('NFC');
    if (!value.trim()) return;
    if (tags.some((tag) => tag.normalize('NFC').toLowerCase() === value.toLowerCase())) {
      setAnnounce('已存在 ' + value);
      return;
    }
    if (full) return;
    const next = [...tags, value];
    commit(next);
    setAnnounce('已添加 ' + value);
    setActive(-1);
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    const size = shown.length;
    switch (event.key) {
      case 'ArrowDown': {
        event.preventDefault();
        if (size === 0) return;
        setActive((index) => (index < 0 ? 0 : (index + 1) % size));
        return;
      }
      case 'ArrowUp': {
        event.preventDefault();
        if (size === 0) return;
        setActive((index) => (index <= 0 ? size - 1 : index - 1));
        return;
      }
      case 'Home': {
        if (size === 0) return;
        event.preventDefault();
        setActive(0);
        return;
      }
      case 'End': {
        if (size === 0) return;
        event.preventDefault();
        setActive(size - 1);
        return;
      }
      case 'Enter': {
        if (active >= 0 && shown[active]) {
          event.preventDefault();
          add(shown[active] as string);
        }
        return;
      }
      case 'Escape': {
        setOpen(false);
        setActive(-1);
        return;
      }
      case 'Backspace': {
        if (query.length === 0 && tags.length > 0) {
          event.preventDefault();
          commit(tags.slice(0, -1));
          setAnnounce('已移除 ' + (tags[tags.length - 1] as string));
        }
        return;
      }
      default:
        return;
    }
  };

  const activeId = active >= 0 && shown[active] ? 'tag-opt-' + active : '';

  return (
    <div>
      <input
        role="combobox"
        aria-expanded={open}
        aria-controls="tag-list"
        aria-autocomplete="list"
        aria-activedescendant={activeId}
        value={query}
        onFocus={() => setOpen(true)}
        onChange={(event) => {
          setQuery(clampByGrapheme(event.target.value, maxLength));
          setOpen(true);
          setActive(-1);
        }}
        onKeyDown={onKeyDown}
      />
      <span data-testid="chars">{graphemes(query).length}</span>
      <span data-testid="remaining">{Math.max(0, maxLength - graphemes(query).length)}</span>
      <span data-testid="limit-note">{full ? '最多 ' + limit + ' 个标签' : ''}</span>
      <ul id="tag-list" role="listbox">
        {shown.map((option, index) => (
          <li
            key={option}
            id={'tag-opt-' + index}
            role="option"
            aria-selected={index === active}
            onMouseDown={(event) => {
              event.preventDefault();
              add(option);
            }}
          >
            {option}
          </li>
        ))}
      </ul>
      {open && normalized.trim().length > 0 && shown.length === 0 ? <span data-testid="no-match">无匹配候选</span> : null}
      <span data-testid="tags">{tags.join('|')}</span>
      <span data-testid="announce" aria-live="polite">
        {announce}
      </span>
    </div>
  );
}

