import { useState } from 'react';

export function TagInput({ options, limit, maxLength = 20, onChange }) {
  const [query, setQuery] = useState('');
  const [tags, setTags] = useState([]);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);

  const matches = options.filter((option) => option.toLowerCase().includes(query.toLowerCase()));

  const add = (value) => {
    if (tags.includes(value)) return;
    const next = [...tags, value];
    setTags(next);
    onChange(next);
  };

  return (
    <div>
      <input
        aria-expanded={open}
        value={query}
        onFocus={() => setOpen(true)}
        onChange={(event) => {
          setQuery(event.target.value.slice(0, maxLength));
          setActive(-1);
        }}
        onKeyDown={(event) => {
          if (event.key === 'ArrowDown') setActive((i) => i + 1);
          if (event.key === 'Enter' && matches[active]) add(matches[active]);
        }}
      />
      <span data-testid="chars">{query.length}</span>
      <span data-testid="remaining">{maxLength - query.length}</span>
      <span data-testid="limit-note" />
      <ul>
        {matches.map((option, index) => (
          <li key={option} id={'tag-opt-' + index} onClick={() => add(option)}>
            {option}
          </li>
        ))}
      </ul>
      <span data-testid="tags">{tags.join('|')}</span>
      <span data-testid="announce" />
    </div>
  );
}
